import{_ as t,a as o,b as a,c as n,d as r}from"./chunks/d96ea9decbc786364a09.CNLo_3aI.js";import{_ as i,o as s,c as l,a6 as h}from"./chunks/framework.CnPv4DE1.js";const b=JSON.parse('{"title":"How To Learn Anything 10X Faster Than Anyone With AI","description":"","frontmatter":{"title":"How To Learn Anything 10X Faster Than Anyone With AI","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/how-to-learn-anything-10x-faster-than-anyone-with-ai.md","filePath":"en/letters/how-to-learn-anything-10x-faster-than-anyone-with-ai.md"}'),p={name:"en/letters/how-to-learn-anything-10x-faster-than-anyone-with-ai.md"};function u(c,e,d,y,m,g){return s(),l("div",null,[...e[0]||(e[0]=[h('<h1 id="how-to-learn-anything-10x-faster-than-anyone-with-ai" tabindex="-1">How To Learn Anything 10X Faster Than Anyone With AI <a class="header-anchor" href="#how-to-learn-anything-10x-faster-than-anyone-with-ai" aria-label="Permalink to &quot;How To Learn Anything 10X Faster Than Anyone With AI&quot;">​</a></h1><p>Dan Koe · 2025-03-01 · <a href="https://thedankoe.com/letters/how-to-learn-anything-10x-faster-than-anyone-with-ai/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/how-to-learn-anything-10x-faster-than-anyone-with-ai">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/FzaHX5rxU34?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>Most people don’t know how to learn.</p><p>They fry their brain with tutorials and podcasts and textbooks but 6 months later they have absolutely nothing to show for it.</p><p>Why are you even learning in the first place if not to <em>do</em> something with it?</p><p>Learning, for most people, has become a form of mental masturbation. It’s the same cheap dopamine you get from scrolling on your phone, but even worse, it makes you feel as if you are learning something (News Flash: you’ll forget about it by tomorrow).</p><p>Here’s the harsh truth:</p><p>You’re learning slow.</p><p>And if you can learn 10x faster, you can achieve success that much faster. You can complete the portfolio project. You can start the business. You can articulate your thoughts on that topic with clarity.</p><p>Even further, you can probably learn something in 2 weeks that takes everyone else 6 months.</p><p>To do that, you need to learn how to learn with:</p><ul><li>The Protege Effect &amp; Feynman Technique</li><li>How to optimize for pattern recognition</li><li>How to use AI to speed up the process</li><li>Project based learning so you actually <em>do</em> something</li></ul><p>This is going to be a very practical letter.</p><p>Please be ready to have your notes open on the side.</p><p>By the end of this, you will have a clear path to learning anything, fast.</p><h2 id="the-meta-skill-–-learning-how-to-learn" tabindex="-1">The Meta Skill – Learning How To Learn <a class="header-anchor" href="#the-meta-skill-–-learning-how-to-learn" aria-label="Permalink to &quot;The Meta Skill – Learning How To Learn&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>The mark of a free person is that they learn how to learn.</p><p>Because if you don’t choose what to learn, you will be told what to learn, and if your mind is the operating system for reality, the options available for your future will be drastically limited, and you won’t even realize it.</p><p>More importantly, the most important thing you can do when the world is changing rapidly is learn. And boy is it changing. Learning is the single most important skill because it’s how you acquire the skills that allow you to take advantage of opportunities that didn’t exist 10 years, 1 year, or even 1 month ago.</p><p>But most people learn wrong.</p><p>And schools rarely change their curriculum.</p><p>Here’s how you take your future into your own hands.</p><h3 id="_1-create-a-map-of-your-ideal-life" tabindex="-1">1) Create A Map Of Your Ideal Life <a class="header-anchor" href="#_1-create-a-map-of-your-ideal-life" aria-label="Permalink to &quot;1) Create A Map Of Your Ideal Life&quot;">​</a></h3><p>I’ve watched countless hours of videos of people teaching how to learn or study faster.</p><p>The single most important thing they’re missing is <em>why they are learning in the first place.</em></p><p>People choose something to learn, <em>but it doesn’t connect to any of their current skills, and it doesn’t connect to the life they want to live.</em></p><p>This is dangerous.</p><p>You won’t <em>want</em> to learn if there is no deeper meaning or clarity behind it.</p><p>You will need more discipline. And you’ll probably continue to hate learning like you did in school. Or you will feel like your learning is for the sole purpose of getting a job or career that you didn’t care about in the first place.</p><p>So that’s step one.</p><p>To create an <em>aim</em> for your learning.</p><p>That way, you can <em>feel</em> the progress you are making toward your self-generated goals, not the goals society assigned to you. That is a major key of life enjoyment (I’ll spare you the psychology around it for now).</p><p>Since I’ve talked about this many times before, and you can fill out this <a href="https://app.kortex.co/public/document/883d9246-6dde-4794-9f54-92b8ff07d502" target="_blank" rel="noreferrer">Simple Life Reset</a> for free (try duplicating the document and asking <a href="https://x.com/thedankoe/status/1895857778180440346" target="_blank" rel="noreferrer">kAI to identify blind spots</a> as you fill it out), let’s keep this part brief.</p><ol><li>Write out what you don’t want in life</li><li>Write out what you want in life</li></ol><p>Write 10+ bullet points for each and bounce between them both.</p><p>These bullet points are your learning filter.</p><p>Without these written down, you will get distracted, and you won’t have a frame of reference that helps optimize for pattern recognition. In other words, your mind won’t notice the things that help you achieve your goals.</p><p>Then, try starting a chat with <a href="https://app.kortex.co/public/document/7a4a85bb-cdfc-4dbd-92b8-d887fa82d224" target="_blank" rel="noreferrer">this prompt</a> I found on X. It’s gold:</p><p><img src="'+o+'" alt=""></p><p>With that context, you can have kAI give you brutally honest advice about what you do and don’t want out of life. You can come back to that chat when you need life advice, like a running journal.</p><h3 id="_2-outline-a-project" tabindex="-1">2) Outline A Project <a class="header-anchor" href="#_2-outline-a-project" aria-label="Permalink to &quot;2) Outline A Project&quot;">​</a></h3><p>Read this carefully:</p><p>The best way to learn is to build a real world project and only search for information when you need it. <em>How much you learn is directly correlated with how much progress you make on the project.</em></p><p>When you watch endless tutorials, you fill your mind with noise and chaos. Most of that information goes to waste. It leads to overwhelm, anxiety, and slows down how fast you learn.</p><p>When it comes time to build the project (the only reason you’re learning in the first place) you feel as if you learned nothing, and have to search for the information anyway. So, if you want to learn faster, skip the tutorial phase. Outline the project first.</p><p>Now, this confuses some people.</p><p>A “project” can be anything.</p><p>Your health can be a project. Your business can be a project. An image in Photoshop can be a project.</p><p>A project is simply a structured way of achieving a goal, or making progress toward a goal.</p><p>It’s a way to further narrow your frame of reference so your mind biases the right information as you learn.</p><p>Again, this continues to optimize pattern recognition.</p><p>As you read books, study tutorials, or have conversations, good dopamine will spurt into your brain to signal that information is important for the completion of the project. Your subconscious will munch on problems and send relevant ideas to your conscious mind.</p><p>This is what creatives call “shower thoughts,” when the Default Mode Network is active in your brain <em>while at “rest.”</em></p><p>Darwin worked on his projects in focused blocks, then went on long walks. On these walks, his brain was at rest, and potential solutions to problems pop into his head.</p><p>When I write newsletters as a small project within a bigger project of my business, I outline the newsletter at the start of the week. This creates my frame of reference. As I’m on walks and having conversations, I <em>feel</em> that sense of excitement when the right idea comes to mind.</p><p>This is when I pull out my phone, open <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex Chats</a>, connect to my newsletter for that week, and save my ideas there so I have it ready the next time I sit down to write during my work blocks.</p><p><strong>Here’s how you start a project:</strong></p><ul><li>Choose something to build that moves the needle toward what you want in life (from earlier)</li><li>Create a note or document and brain dump everything that comes to mind</li><li>Save 3-5 sources of inspiration that you want to emulate (if I’m creating a YouTube video as a project, I would save 3-5 YouTube videos I would want to create similar iterations of)</li><li>Study those sources and break down their structure or characteristics</li><li>Outline the project into sections, milestones, images, inspiration, and what you need to know</li><li>Have a place to capture ideas that comes to mind, preferably somewhere you don’t lose the ideas or forget about them</li></ul><p>Now that you’re ready to start, don’t start learning.</p><h3 id="_3-start-with-what-you-know" tabindex="-1">3) Start With What You Know <a class="header-anchor" href="#_3-start-with-what-you-know" aria-label="Permalink to &quot;3) Start With What You Know&quot;">​</a></h3><p>Learning comes from struggle, not memorization.</p><p>Start the project. No, don’t watch 20 tutorials beforehand. Let it expose the gaps in your knowledge. Try to figure it out. Search for the answer when your mind is most likely to remember it.</p><p>Whether you’re learning Photoshop or learning to program, start with what you know.</p><p>If you know nothing, at least try to take the first step. Download the software and start playing around. Try to create <em>something. Anything.</em> Just get your mind in a state where it’s <em>hungry</em> to learn. Otherwise, you probably won’t <em>digest</em> the information you search for.</p><p>Then, follow this process:</p><ul><li>You don’t know what to do</li><li>You try and fail</li><li>Search for the answer or ask AI</li><li>Try to implement the answer</li><li>Repeat until the project is complete</li><li>If you can’t find the answer, ask an expert</li></ul><p>A few years ago, Google searching was a skill.</p><p>Now that AI can provide more relevant information fast, prompting is a skill.</p><p>Think of AI not as a machine who does work for you, but a creative sparring partner. Sometimes one sentence prompts can do the trick, but the output of AI is only as good as you are when it comes to creative work.</p><p>If I’m building a Photoshop project and don’t know how to remove a background, I can simply ask, “How do I remove the background of a photo in Photoshop” to kAI and it will give me exact steps to do.</p><p>Then, I can ask it even more questions, like what Selections and Masks are, and learn on the spot. On the Kortex desktop app, you can press Alt or Option+C to open up floating chats and ask AI without going to another website or leaving your place.</p><h3 id="_3-5-how-to-start-when-you-don-t-feel-like-starting" tabindex="-1">3.5) How To Start When You Don’t Feel Like Starting <a class="header-anchor" href="#_3-5-how-to-start-when-you-don-t-feel-like-starting" aria-label="Permalink to &quot;3.5) How To Start When You Don’t Feel Like Starting&quot;">​</a></h3><p>The Zeigarnik Effect is a psychological phenomenon where people remember unfinished tasks more than completed tasks.</p><p>Meaning, if we don’t complete tasks for our project, it’s much easier to find the motivation to get started.</p><p>But how do you get started from scratch?</p><p>There’s a trick I learned from <a href="https://www.youtube.com/@JustinSung" target="_blank" rel="noreferrer">Justin Sung</a> that he calls the Zeigarnik² Effect. In other words, doing easy tasks before you start to simulate the feeling of having unfinished tasks.</p><p>This could be a work ritual like making coffee, cleaning your desk, or going on a morning walk and jotting notes on your phone.</p><p>How I like to think of this is breaking down the task you need to start <em>into the simplest possible action you can take.</em></p><p>For something like writing, that’s sitting at your desk, opening up your outline, and simply reading it over. That requires very little motivation.</p><p>Now, if you want to take this effect even further, just open up an AI tool and use <a href="https://app.kortex.co/public/document/7a4a85bb-cdfc-4dbd-92b8-d887fa82d224" target="_blank" rel="noreferrer">this prompt</a>:</p><p><img src="'+a+'" alt=""></p><p>I told Joey to pop that into <a href="https://kortex.co/" target="_blank" rel="noreferrer">kAI</a> and he changed it a bit and… yeah…</p><p><img src="'+n+'" alt=""></p><p>Try it out.</p><h3 id="_4-create-a-study-regimen" tabindex="-1">4) Create A Study Regimen <a class="header-anchor" href="#_4-create-a-study-regimen" aria-label="Permalink to &quot;4) Create A Study Regimen&quot;">​</a></h3><p>Now that you have a frame of reference, project outline, and have started making progress—you can start supplementing with general learning and tutorials.</p><p>Create a new chat and try <a href="https://app.kortex.co/public/document/7a4a85bb-cdfc-4dbd-92b8-d887fa82d224" target="_blank" rel="noreferrer">this prompt</a>:</p><p><img src="'+r+'" alt=""></p><p>For [topic], you can enter anything from Photoshop to storytelling to content creation.</p><p>The best way to structure your learning, in my opinion, is in 3 types of timeblocks:</p><ol><li><strong>30-90 Minutes Of Building</strong> – build your project and search for information when you need it.</li><li><strong>30-60 Minutes of Learning</strong> – follow your study regimen and take notes on what you learn. You can review these notes by asking your notes to be summarized in kAI.</li><li><strong>30 Minutes of Walking</strong> – for YouTube videos, audiobooks, or lectures go on a walk and jot down ideas on your phone as they come to mind.</li></ol><p>Those are your keystone habits.</p><p>Nobody is going to give you the time to learn and build.</p><p>You have to take the time. Put them on your calendar. Wake up an hour earlier or stay up an hour later. Turn it into a ritual.</p><p>Grab your coffee, pull up your outline, put on some focus music, and start paving the way toward the future you want to create.</p><h2 id="write-to-systematically-reflect-on-what-you-learn" tabindex="-1">Write To Systematically Reflect On What You Learn <a class="header-anchor" href="#write-to-systematically-reflect-on-what-you-learn" aria-label="Permalink to &quot;Write To Systematically Reflect On What You Learn&quot;">​</a></h2><p>Here’s the puzzle:</p><ul><li>You know what you want for your future</li><li>You have a project (or series of projects) that will take you there</li><li>You are learning and building daily</li></ul><p>But there’s one missing piece.</p><p>And it turns out, it’s also a way to <em>further</em> enhance how much you learn.</p><p>The missing piece is <em>people who care about what you’re building.</em></p><p>I’m assuming you want to do this full time.</p><p>You’re learning and building because you want that to turn into some kind of sustainable life. You want to replace your job or career with a calling. An obsession.</p><p>To do that you need money. At least enough to sustain your ideal life.</p><p>To make money, you need people to care about what you’re building.</p><p>To make people care about what you’re building, you need to show what you’re doing in public.</p><p>In most cases, the best way to do that is writing.</p><p>Teaching what you know and what you’re learning as you build.</p><p>Why writing?</p><p>Well first, it’s the foundation of media. Two, it’s accessible and anyone can start writing right now, no video editing skills required. Three, it holds much more power than just building an audience of supporters.</p><p>Writing is how you systematically reflect on what you learn.</p><p>When you teach what you learn, you expose <em>more</em> knowledge gaps. You struggle more to understand. You have more specific knowledge to research.</p><p>This is where the Feynman Technique and Protege Effect come into play.</p><p>The Feynman Technique is a learning method popularized by physicist Richard Feynman. In short, it’s about deeply understanding a concept by explaining it in simple terms as if you were teaching it to someone with no prior knowledge:</p><ul><li><strong>Choose a concept –</strong> Select the topic you want to understand.</li><li><strong>Teach it –</strong> Explain the concept in simple language, as if you were teaching it to a child.</li><li><strong>Identify gaps –</strong> When you struggle to explain something clearly, identify the areas where your understanding is weak.</li><li><strong>Review and simplify –</strong> Go back to the source material, relearn the concepts, and then try explaining them again in even simpler terms.</li></ul><p>This overlaps with the Protege Effect which is, in summary, that the teacher learns more than the student.</p><p>Teaching what you learn encourages you to make sense of your experience in your own way. It exposes even more gaps in your knowledge, increasing the effect of pattern recognition. Life becomes sustainably more enjoyable and serendipitous because you no longer need distractions for pleasure.</p><p>How do we merge both of these with how you are already learning?</p><p>By writing on the internet.</p><p>We talk about this in almost every newsletter, but I’m not talking about becoming a content creator.</p><p>I’m talking about treating social media as your public journal.</p><p>That way, you at least <em>have a chance</em> at attracting potential supporters, customers, employers, investors, team members, and anything else you would need to reach the life you want.</p><p>It’s less about building a following, and more about putting your work in front of other people. Like when you’re trying to meet new people, it’s never going to happen if you don’t get out of your house, and you’ll grow bitter and angry wondering why you’re all alone. It’s obvious why… because you haven’t given people a chance to know or care about you. Your chances of success are zero.</p><p>Here’s what I recommend for starting:</p><ul><li>Write a newsletter once a week to summarize what you’ve learned</li><li>Remember, teach it to them. Don’t make it a boring dump of information.</li><li>Write posts on X, Threads, or LinkedIn (writing platforms, easy to access)</li><li>Talk about your opinions, beliefs, personal experiences, and what you are learning and building</li><li>Tack on “social media” as a skill you need to learn the same way as taught in this letter</li><li>Add one more 30-60 minute time block for writing every morning</li><li>Ask kAI to help you as you write, i.e. “You are an expert at crafting engaging social posts. Whats the best way to start a post on [topic]?” and continue from there.</li></ul><p>Personally, writing changed my life.</p><p>I was once a freelance web designer who failed at every business he tried prior to that.</p><p>I started on social media because I was tired of doing cold outreach to land clients.</p><p>As I kept going, I realized how powerful writing could be to get in front of the right people (so I didn’t have to get rejected so much, people came to me).</p><p>But it wasn’t just about the freelance work.</p><p>It was about how much I was learning.</p><p>Every time I hit post, I felt as if I had learned something new.</p><p>I could see a path to becoming the “intelligent” person that I had always admired as a kid.</p><p>The more I wrote, the more good things happened internally and externally.</p><p>I hope that you too can experience that.</p><p>Now, you don’t need to enroll in the Writer’s Bootcamp, but it is an option to include in your “study regimen” from above.</p><p>The start date is March 4th. 3 days from now. So if you want to learn the ins and outs of newsletters, threads, posts, YouTube video scripts, and building an AI powered second brain of ideas in Kortex, <a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">consider enrolling here.</a></p><p>Thank you for reading.</p><p>– Dan</p>',141)])])}const k=i(p,[["render",u]]);export{b as __pageData,k as default};
